import java.util.*;
import java.io.*;

public class _1599_C_Variant1 {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(tokenizer.nextToken());
        double p = Double.parseDouble(tokenizer.nextToken());
        int totalWays = computeChooseThree(n);
        for (int i = 0; i <= n; i++) {
            double probability = 0;
            double p1 = (double) i * computeChooseTwo(n - i) / totalWays;
            double p2 = (double) computeChooseTwo(i) * (n - i) / totalWays;
            double p3 = (double) computeChooseThree(i) / totalWays;
            probability = p1 / 2 + p2 + p3;
            if (probability >= p) {
                writer.println(i);
                break;
            }
        }
        reader.close();
        writer.close();
    }

    static int computeChooseTwo(int n) {
        if (n < 2) return 0;
        return n * (n - 1) / 2;
    }

    static int computeChooseThree(int n) {
        if (n < 3) return 0;
        return n * (n - 1) * (n - 2) / 6;
    }
}
